async function main() {
  try {
    const payload = parsePayload(process.argv[2]);
    const uid = await ownerId();
    const result = payload.command === 'spmtpreviewrestore' ? await restoreNativePreviews(uid) : payload.command === 'spmtmedia' ? await inspectStudioMedia(uid) : ['spmtpreviewoff','spmtpreviewon'].includes(payload.command) ? await setLocalPreview(uid,payload.command) : payload.command === 'spmtpreviewunloadtest' ? await testLocalPreviewUnload(uid) : payload.command === 'spmtpreviewtest' ? await testLocalPreview(uid) : payload.command === 'spmtsharedscale' ? await scaleSharedBrowserHost(uid) : payload.command === 'spmthostrestart' ? await restartOfflineHost(uid) : payload.command === 'spmtstart' ? await startRestream(uid) : await inspect(uid);
    process.stdout.write(JSON.stringify(result, null, 2));
  } catch (error) {
    process.stdout.write(JSON.stringify({ ok:false, error:redact(error instanceof Error ? error.message : error) }, null, 2));
    process.exitCode = 1;
  }
}

